<!DOCTYPE html><html><head><meta charset="utf-8"><style>@page{margin:28px}body{font-family:DejaVu Sans,sans-serif;color:#17212a;font-size:10px}h1{margin:0;font-size:24px}.brand{color:#087a4e;font-weight:bold;letter-spacing:2px}.meta{color:#68747d;margin:6px 0 22px}table{width:100%;border-collapse:collapse}th{background:#111820;color:#fff;text-align:left;padding:9px 7px;font-size:9px}td{border-bottom:1px solid #dfe4e8;padding:9px 7px;vertical-align:top}.muted{color:#68747d;font-size:9px}.status{font-weight:bold;text-transform:capitalize}.total{margin-top:16px;text-align:right;font-size:13px}.footer{position:fixed;bottom:-12px;left:0;right:0;color:#89939a;font-size:8px;text-align:right}</style></head><body><div class="brand">PROFLECT</div><h1>Payment History Report</h1><div class="meta">Generated {{ now()->format('d M Y, h:i A') }} | {{ $payments->count() }} records, including free plan activations</div><table><thead><tr><th>Record ID</th><th>Customer</th><th>Plan</th><th>Type</th><th>Amount</th><th>Date</th><th>Status</th></tr></thead><tbody>@forelse($payments as $payment)<tr><td>{{ $payment->gateway === 'free' ? 'FREE-'.str_pad($payment->id,6,'0',STR_PAD_LEFT) : ($payment->gateway_payment_id ?: $payment->gateway_order_id) }}</td><td>{{ $payment->user->name }}<br><span class="muted">{{ $payment->user->email }}</span></td><td>{{ $payment->plan->name }}</td><td>{{ $payment->gateway === 'free' ? 'Free plan activation' : ucfirst($payment->gateway) }}</td><td>{{ $payment->amount ? 'INR '.number_format($payment->amount/100,2) : 'Free' }}</td><td>{{ ($payment->paid_at ?? $payment->created_at)->format('d M Y') }}</td><td class="status">{{ str_replace('_',' ',$payment->status) }}</td></tr>@empty<tr><td colspan="7">No payments found.</td></tr>@endforelse</tbody></table><div class="total"><b>Paid total: INR {{ number_format($payments->where('status','paid')->sum('amount')/100,2) }}</b></div><div class="footer">Proflect Payment History Report</div></body></html>
